import{_ as e,c as n,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Spielerstimmen","description":"","frontmatter":{},"headers":[],"relativePath":"de/testimonials.md","filePath":"de/testimonials.md"}');const a=e({name:"de/testimonials.md"},[["render",function(e,t,a,s,h,l){return i(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="spielerstimmen" tabindex="-1">Spielerstimmen <a class="header-anchor" href="#spielerstimmen" aria-label="Permalink to &quot;Spielerstimmen&quot;">​</a></h1><p>Echtes Feedback von Elite-Pétanque-Spielern, die die Ressourcen der Pétanque Academy genutzt haben, um ihr mentales Spiel und ihre Wettkampfleistung zu verbessern.</p><div class="tip custom-block"><p class="custom-block-title">Authentisch &amp; Anonym</p><p>Diese Erfahrungsberichte stellen authentisches Feedback von Spielern verschiedener Leistungsklassen dar. Alle Erfahrungsberichte sind anonym, um die Privatsphäre der Spieler zu schützen und einen ehrlichen Austausch zu fördern.</p></div><h2 id="regionale-und-nationale-wettbewerber" tabindex="-1">Regionale und nationale Wettbewerber <a class="header-anchor" href="#regionale-und-nationale-wettbewerber" aria-label="Permalink to &quot;Regionale und nationale Wettbewerber&quot;">​</a></h2><h3 id="„das-inner-coach-framework-hat-alles-verandert" tabindex="-1">„Das Inner Coach Framework hat alles verändert.“ <a class="header-anchor" href="#„das-inner-coach-framework-hat-alles-verandert" aria-label="Permalink to &quot;„Das Inner Coach Framework hat alles verändert.“&quot;">​</a></h3><blockquote><p>„Ich spiele seit zwölf Jahren Pétanque im Wettkampf und dachte, ich wüsste alles darüber. Aber ich war mein eigener größter Feind – ich habe mich nach jedem Fehler ständig selbst kritisiert. Das Konzept des inneren Trainers versus des inneren Kritikers aus dem Modul „Mentale Stärke“ hat mir eine völlig neue Art der Selbstgespräche während des Wettkampfs ermöglicht.“</p><p>Innerhalb von zwei Monaten bemerkten meine Teamkollegen den Unterschied. Ich war ruhiger, erholte mich schneller von Fehlwürfen und hatte wieder richtig Spaß am Wettkampf. Dieses Jahr belegte ich den 3. Platz bei den Regionalmeisterschaften – mein bisher bestes Ergebnis.</p></blockquote><p><strong>— Regionalmeister, Frankreich</strong></p><hr><h3 id="„endlich-jemand-der-die-entwicklung-von-spitzensportlern-versteht" tabindex="-1">„Endlich jemand, der die Entwicklung von Spitzensportlern versteht.“ <a class="header-anchor" href="#„endlich-jemand-der-die-entwicklung-von-spitzensportlern-versteht" aria-label="Permalink to &quot;„Endlich jemand, der die Entwicklung von Spitzensportlern versteht.“&quot;">​</a></h3><blockquote><p>*„Das meiste Pétanque-Training besteht nur aus ‚mehr üben‘ oder ‚an der Technik arbeiten‘. Aber wenn man schon über 15 Jahre spielt, ist das nicht das Problem. Das Problem ist, unter Druck auf die eigene Technik zuzugreifen.“</p><p>Das Zone-Modul erklärte genau, was ich erlebte – zu viel Nachdenken während der Ausführung, Verharren im analytischen Modus, obwohl ich im Flow sein musste. Die praktischen Techniken zum Umschalten der Modi waren bahnbrechend.</p><p><em>Dies ist die erste Quelle, die ich gefunden habe, die sich tatsächlich mit dem mentalen Aspekt des Spiels auf Spitzenniveau auseinandersetzt.</em></p></blockquote><p><strong>— Nationalspieler, Schweden</strong></p><hr><h3 id="„die-workshop-methodik-hat-unseren-club-verandert" tabindex="-1">„Die Workshop-Methodik hat unseren Club verändert.“ <a class="header-anchor" href="#„die-workshop-methodik-hat-unseren-club-verandert" aria-label="Permalink to &quot;„Die Workshop-Methodik hat unseren Club verändert.“&quot;">​</a></h3><blockquote><p><em>„Ich bin Vereinstrainer und habe den Workshop-Leitfaden genutzt, um eine Mentaltrainingseinheit mit unseren acht besten Spielern durchzuführen. Das Konzept der psychologischen Sicherheit und das strukturierte Diskussionsformat ermöglichten Gespräche, die wir zuvor noch nie geführt hatten.“</em></p><p>Die Spieler sprachen offen über ihre inneren Kritiker, ihre Reaktionen auf Druck und ihre Kommunikationsschwierigkeiten im Team. Das war unglaublich eindrucksvoll. Wir führen diese Sitzungen nun monatlich durch, und die Teamkultur hat sich komplett verändert.</p></blockquote><p><strong>— Vereinstrainer, Deutschland</strong></p><hr><h2 id="turnierspieler" tabindex="-1">Turnierspieler <a class="header-anchor" href="#turnierspieler" aria-label="Permalink to &quot;Turnierspieler&quot;">​</a></h2><h3 id="quot-praktische-werkzeuge-die-tatsachlich-funktionieren-quot" tabindex="-1">&quot;Praktische Werkzeuge, die tatsächlich funktionieren&quot; <a class="header-anchor" href="#quot-praktische-werkzeuge-die-tatsachlich-funktionieren-quot" aria-label="Permalink to &quot;&amp;quot;Praktische Werkzeuge, die tatsächlich funktionieren&amp;quot;&quot;">​</a></h3><blockquote><p>„Ich habe schon Bücher über Sportpsychologie gelesen, aber die sind immer entweder zu allgemein oder zu akademisch. Die Ziel- und Tagebuchvorlage der Pétanque Academy sind genau das, was ich brauchte – praxisnah, speziell auf Pétanque zugeschnitten und sofort einsatzbereit.“</p><p>„Ich habe die Zielvorlage verwendet und innerhalb von 30 Minuten einen klaren 3-Monats-Entwicklungsplan erstellt. Die Tagebuchvorlage hilft mir, nicht nur Ergebnisse, sondern auch meine mentale Leistungsfähigkeit zu verfolgen. Diese Tools sind Gold wert.“</p></blockquote><p><strong>— Turnierspieler, Spanien</strong></p><hr><h3 id="„die-achtsamkeitstechniken-wirken-im-wettbewerb" tabindex="-1">„Die Achtsamkeitstechniken wirken im Wettbewerb.“ <a class="header-anchor" href="#„die-achtsamkeitstechniken-wirken-im-wettbewerb" aria-label="Permalink to &quot;„Die Achtsamkeitstechniken wirken im Wettbewerb.“&quot;">​</a></h3><blockquote><p>*„Ich war skeptisch gegenüber Achtsamkeit – sie schien mir für Leistungssport zu ‚weich‘. Aber die Techniken im Achtsamkeitsmodul sind praxisnah und konkret. Die Drei-Atemzüge-Übung, der Bodyscan zur Erkennung von Verspannungen, die Übungen zur Konzentration auf den gegenwärtigen Moment.“</p><p>Ich übe jeden Morgen 10 Minuten und kann diese Techniken jetzt auch im Wettkampf anwenden. Wenn ich merke, dass der Druck steigt, habe ich die Mittel, damit umzugehen. Das hat meine Leistung spürbar verbessert.</p></blockquote><p><strong>— Turnierspieler, Niederlande</strong></p><hr><h3 id="„das-verstandnis-von-flow-zustanden-hat-mein-potenzial-freigesetzt" tabindex="-1">„Das Verständnis von Flow-Zuständen hat mein Potenzial freigesetzt.“ <a class="header-anchor" href="#„das-verstandnis-von-flow-zustanden-hat-mein-potenzial-freigesetzt" aria-label="Permalink to &quot;„Das Verständnis von Flow-Zuständen hat mein Potenzial freigesetzt.“&quot;">​</a></h3><blockquote><p>„Ich hatte schon Spiele erlebt, in denen einfach alles passte – in denen ich nicht nachdachte, sondern einfach perfekt spielte. Aber ich wusste nicht, wie ich diesen Zustand dauerhaft erreichen konnte. Das Zone-Modul erklärte mir die wissenschaftlichen Hintergründe und gab mir praktische Techniken an die Hand.“</p><p><em>Das Wissen um vorübergehende Hypofrontalität, das Verständnis des Wechsels zwischen Planung und Ausführung, das Üben von Flow-Auslösern – all das hat mir geholfen, Höchstleistungszustände viel leichter zu erreichen. Ich spiele gerade mein bestes Boule aller Zeiten.</em></p></blockquote><p><strong>— Regionalspieler, Frankreich</strong></p><hr><h2 id="teamspieler" tabindex="-1">Teamspieler <a class="header-anchor" href="#teamspieler" aria-label="Permalink to &quot;Teamspieler&quot;">​</a></h2><h3 id="quot-wurde-zum-teamkollegen-den-sich-jeder-wunscht-quot" tabindex="-1">&quot;Wurde zum Teamkollegen, den sich jeder wünscht&quot; <a class="header-anchor" href="#quot-wurde-zum-teamkollegen-den-sich-jeder-wunscht-quot" aria-label="Permalink to &quot;&amp;quot;Wurde zum Teamkollegen, den sich jeder wünscht&amp;quot;&quot;">​</a></h3><blockquote><p>*„Technisch war ich stark, hatte aber Schwierigkeiten in Mannschaftswettbewerben. Das Modul Teamdynamik hat mir gezeigt, dass es bei einem guten Teamplayer nicht nur um gute Würfe geht, sondern auch um Kommunikation, Vertrauen und psychologische Sicherheit.“</p><p>Ich lernte, Vertrauen auszudrücken, Strategien klar zu kommunizieren und Teamkollegen nach Fehlern zu unterstützen. Innerhalb weniger Monate wurde ich von einem gemiedenen zu einem gefragten Partner. Dieses Jahr gewannen wir die regionale Teammeisterschaft.</p></blockquote><p><strong>— Mannschaftsspieler, Italien</strong></p><hr><h3 id="„das-kommunikationskonzept-hat-unsere-partnerschaft-gerettet" tabindex="-1">„Das Kommunikationskonzept hat unsere Partnerschaft gerettet.“ <a class="header-anchor" href="#„das-kommunikationskonzept-hat-unsere-partnerschaft-gerettet" aria-label="Permalink to &quot;„Das Kommunikationskonzept hat unsere Partnerschaft gerettet.“&quot;">​</a></h3><blockquote><p>„Meine feste Partnerin und ich hatten Spannungen – unterschiedliche Spielstile, mangelnde Kommunikation, zunehmende Frustration. Das Teamplayer-Modul bot uns einen Rahmen, um dies konstruktiv zu besprechen.“</p><p>Wir haben etwas über Kommunikationsmuster, Vertrauensaufbau und die Schaffung psychologischer Sicherheit gelernt. Im Workshop-Format führten wir offene Gespräche. Unsere Partnerschaft ist stärker denn je, und unsere Ergebnisse belegen dies.</p></blockquote><p><strong>— Doppelteam, Norwegen</strong></p><hr><h2 id="trainer-und-coaches" tabindex="-1">Trainer und Coaches <a class="header-anchor" href="#trainer-und-coaches" aria-label="Permalink to &quot;Trainer und Coaches&quot;">​</a></h2><h3 id="„so-sieht-elite-coaching-aus" tabindex="-1">„So sieht Elite-Coaching aus.“ <a class="header-anchor" href="#„so-sieht-elite-coaching-aus" aria-label="Permalink to &quot;„So sieht Elite-Coaching aus.“&quot;">​</a></h3><blockquote><p>„Ich trainiere seit 20 Jahren Pétanque und habe mich hauptsächlich auf die Technik konzentriert. Aber ich habe gesehen, wie Spieler mit exzellenter Technik unter Druck versagten. Die Schulungsmodule gaben mir den Rahmen, um das mentale Spiel systematisch anzugehen.“</p><p><em>Der Leitfaden für das Trainingslager half mir, ein Wochenendprogramm zu strukturieren, das technisches Training mit mentalem Spieltraining kombinierte. Das Feedback der Spieler war unglaublich – sie sagten, es sei das wertvollste Training gewesen, an dem sie je teilgenommen hätten.</em></p></blockquote><p><strong>— Trainer, Frankreich</strong></p><hr><h3 id="„evidenzbasierter-ansatz-fur-mentales-training" tabindex="-1">„Evidenzbasierter Ansatz für mentales Training“ <a class="header-anchor" href="#„evidenzbasierter-ansatz-fur-mentales-training" aria-label="Permalink to &quot;„Evidenzbasierter Ansatz für mentales Training“&quot;">​</a></h3><blockquote><p>*„Was ich am meisten schätze, ist, dass es sich hier nicht nur um leere Motivationsfloskeln handelt. Die Inhalte basieren auf tatsächlicher psychologischer Forschung – Flow-Zustand-Forschung, Achtsamkeitsstudien, Leistungspsychologie. Und sie werden in praktische, umsetzbare Techniken übersetzt.“</p><p><em>Ich nutze diese Module als Grundlage für das Mentaltraining meiner Spitzenspieler. Der strukturierte Ansatz, die klaren Rahmenbedingungen, die praktischen Übungen – das ist Inhalt auf Profi-Niveau.</em></p></blockquote><p><strong>— Sportpsychologe und Pétanque-Trainer, Großbritannien</strong></p><hr><h2 id="gemeinsame-themen" tabindex="-1">Gemeinsame Themen <a class="header-anchor" href="#gemeinsame-themen" aria-label="Permalink to &quot;Gemeinsame Themen&quot;">​</a></h2><h3 id="was-spieler-am-meisten-schatzen" tabindex="-1">Was Spieler am meisten schätzen <a class="header-anchor" href="#was-spieler-am-meisten-schatzen" aria-label="Permalink to &quot;Was Spieler am meisten schätzen&quot;">​</a></h3><p>Laut Spielerfeedback heben die Spieler immer wieder Folgendes hervor:</p><ol><li><strong>Praktische, umsetzbare Inhalte</strong> – Keine Theorie, sondern Techniken, die Sie heute anwenden können.</li><li><strong>Pétanque-spezifisch</strong> – Entwickelt für die einzigartigen Herausforderungen des Pétanque</li><li><strong>Fokus auf Spitzenniveau</strong> – Konzentriert sich auf die mentale Stärke, nicht auf die grundlegende Technik.</li><li><strong>Strukturierte Rahmenbedingungen</strong> – Klare Systeme statt vager Ratschläge</li><li><strong>Kostenlos und barrierefrei</strong> – Keine Bezahlschranken, für alle verfügbar</li></ol><h3 id="messbare-ergebnisse" tabindex="-1">Messbare Ergebnisse <a class="header-anchor" href="#messbare-ergebnisse" aria-label="Permalink to &quot;Messbare Ergebnisse&quot;">​</a></h3><p>Spieler berichten von Verbesserungen in folgenden Bereichen:</p><ul><li>Wettbewerbsleistung und Ergebnisse</li><li>Beständigkeit unter Druck</li><li>Erholungszeit nach Fehlern</li><li>Teamkommunikation und -dynamik</li><li>Freude am Wettbewerb</li><li>Mentale Widerstandsfähigkeit</li></ul><h2 id="teilen-sie-ihre-erfahrungen" tabindex="-1">Teilen Sie Ihre Erfahrungen <a class="header-anchor" href="#teilen-sie-ihre-erfahrungen" aria-label="Permalink to &quot;Teilen Sie Ihre Erfahrungen&quot;">​</a></h2><p>Haben Sie schon einmal die Angebote der Pétanque Academy genutzt? Wir würden uns freuen, von Ihren Erfahrungen zu hören.</p><p><strong>Senden Sie Ihre Kundenmeinung per E-Mail an:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Testimonial" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Enthalten:</strong></p><ul><li>Ihr Erfahrungsniveau</li><li>Welche Ressourcen haben Sie verwendet?</li><li>Welche Auswirkungen hatten sie?</li><li>Ob wir Ihr Feedback weitergeben dürfen (Name optional)</li></ul><p>Deine Geschichte könnte anderen Spielern helfen, diese Ressourcen zu entdecken.</p><hr><h2 id="los-geht-39-s" tabindex="-1">Los geht&#39;s <a class="header-anchor" href="#los-geht-39-s" aria-label="Permalink to &quot;Los geht&amp;#39;s&quot;">​</a></h2><p>Bereit, deine mentale Stärke zu verbessern?</p><div class="tip custom-block"><p class="custom-block-title">Hier beginnen</p><ul><li><strong>Neu im Bereich Mentaltraining?</strong> → <a href="/en/education/the-zone/">The Zone</a></li><li><strong>Sie fühlen sich unter Druck gesetzt?</strong> → <a href="/en/education/mental-strength/">Mentale Stärke</a></li><li><strong>Teamherausforderungen?</strong> → <a href="/en/education/team-player/">Teamdynamik</a></li><li><strong>Sie wünschen sich Struktur?</strong> → <a href="/en/goal-template">Zielvorlage</a></li></ul></div>',64)])])}]]);export{t as __pageData,a as default};
